// POC ONLY — poc/http-ingress-b — do not merge as production API.
//
// Minimal synchronous HTTP ingress bridge, built on Node's built-in `http`
// module only (no new dependency added: `express` already exists in this
// monorepo's node_modules tree as a transitive Node-RED dep, but this PoC
// avoids relying on that hoisting detail entirely). Exposes POST /poc/sync:
//   1. Builds the same serializable envelope PoC A uses.
//   2. Starts a real `executeFlow` Workflow with that envelope as startMsg.
//   3. `await`s `handle.result()` for the FULL Workflow completion.
//   4. Writes the real HTTP response using the response descriptor Option 1
//      threads back out via the Workflow's returned `lastMsg.payload`
//      (see the tiny, loudly-marked diff in ../../lib/workflows.js).
//
// This proves PoC B: an ordinary synchronous HTTP request/response can be
// backed end-to-end by a durable Temporal Workflow, surviving an Activity
// worker restart mid-flight (B4) while only losing the HTTP socket (not the
// Workflow) if the bridge itself is killed (B5) or the client disconnects
// (B6).
//
// Usage:
//   TEMPORAL_ADDRESS=127.0.0.1:7249 \
//   TEMPORAL_WORKFLOW_TASK_QUEUE=poc-http-ingress-b \
//   TEMPORAL_ACTIVITY_TASK_QUEUE=poc-http-ingress-b \
//   node sync-server.js
//
// See README.md in this directory for full experiment logs.

"use strict";

const http = require("http");
const path = require("path");
const fs = require("fs");
const { Client, Connection } = require("@temporalio/client");
const { extractWireGraph, extractNodeMeta } = require("../../lib/wireGraph");
const { computeFlowVersion } = require("../../lib/bootstrap");
const { resolveTemporalConfig } = require("../../lib/worker");

const PORT = Number(process.env.POC_HTTP_PORT || 3940);
const FLOW_PATH = process.env.POC_FLOW_PATH || path.join(__dirname, "flow.json");
const START_NODE = process.env.POC_START_NODE || "n1";

let clientPromise;
function getClient() {
    if (!clientPromise) {
        const temporalConfig = resolveTemporalConfig({});
        clientPromise = Connection.connect({ address: temporalConfig.address }).then((connection) => ({
            client: new Client({ connection, namespace: temporalConfig.namespace }),
            temporalConfig
        }));
    }
    return clientPromise;
}

// Reads the incoming request into a fully serializable envelope: no req/
// res/socket reference is ever placed on the envelope, only plain data.
function readBody(req) {
    return new Promise((resolve, reject) => {
        const chunks = [];
        req.on("data", (chunk) => chunks.push(chunk));
        req.on("end", () => {
            const raw = Buffer.concat(chunks).toString("utf8");
            if (!raw) {
                return resolve(undefined);
            }
            try {
                resolve(JSON.parse(raw));
            } catch (err) {
                resolve(raw);
            }
        });
        req.on("error", reject);
    });
}

function toEnvelope(req, url, body) {
    return {
        method: req.method,
        url: req.url,
        headers: Object.assign({}, req.headers),
        query: Object.fromEntries(url.searchParams.entries()),
        body
    };
}

const server = http.createServer(async (req, res) => {
    // B6: guard against writing to a socket the client already closed -
    // without this, res.end() on a torn-down connection can surface as an
    // uncaught 'error' event instead of a caught exception.
    res.on("error", (err) => {
        console.error("[poc-sync] response socket error (client likely disconnected):", err.message);
    });

    const url = new URL(req.url, `http://${req.headers.host || "localhost"}`);

    if (req.method !== "POST" || url.pathname !== "/poc/sync") {
        res.writeHead(404, { "content-type": "application/json" });
        res.end(JSON.stringify({ error: "not found" }));
        return;
    }

    let workflowId;
    try {
        const body = await readBody(req);
        const envelope = toEnvelope(req, url, body);

        const flows = JSON.parse(fs.readFileSync(FLOW_PATH, "utf8"));
        const graph = extractWireGraph(flows);
        const nodeMeta = extractNodeMeta(flows);
        const flowVersion = computeFlowVersion(flows);

        const { client, temporalConfig } = await getClient();
        workflowId = `poc-http-ingress-b-${Date.now()}`;
        const handle = await client.workflow.start("executeFlow", {
            taskQueue: temporalConfig.workflowTaskQueue,
            workflowId,
            args: [{
                graph,
                nodeMeta,
                flowVersion,
                startNode: START_NODE,
                startMsg: { payload: envelope },
                activityTaskQueue: temporalConfig.activityTaskQueue
            }]
        });

        console.log(`[poc-sync] started workflow ${handle.workflowId} (runId ${handle.firstExecutionRunId})`);

        // Blocks until the FULL Workflow completes (including any worker
        // restarts/timers in between) - this is the synchronous bridge.
        const result = await handle.result();
        console.log(`[poc-sync] workflow ${handle.workflowId} completed:`, JSON.stringify(result));

        const descriptor = result && result.lastMsg && result.lastMsg.payload;
        if (!descriptor || typeof descriptor.statusCode !== "number") {
            throw new Error(`workflow did not produce a response descriptor: ${JSON.stringify(result)}`);
        }

        const headers = Object.assign({ "content-type": "application/json" }, descriptor.headers || {});
        res.writeHead(descriptor.statusCode, headers);
        res.end(JSON.stringify(descriptor.payload));
    } catch (err) {
        console.error(`[poc-sync] error (workflowId=${workflowId}):`, err);
        // B6: writing to an already-closed/reset socket must fail
        // gracefully, not crash the process - guard every response write.
        try {
            if (!res.headersSent) {
                res.writeHead(500, { "content-type": "application/json" });
            }
            res.end(JSON.stringify({ error: err.message, workflowId }));
        } catch (writeErr) {
            console.error("[poc-sync] failed to write error response (socket likely gone):", writeErr.message);
        }
    }
});

// B6 safety net: a client that disconnects mid-request can still cause an
// EPIPE/ECONNRESET when the response is written later - catch it on the
// socket/req itself so it never becomes an uncaught exception.
server.on("clientError", (err, socket) => {
    console.error("[poc-sync] clientError:", err.message);
    if (socket.writable) {
        socket.end("HTTP/1.1 400 Bad Request\r\n\r\n");
    }
});

server.listen(PORT, () => {
    console.log(`[poc-sync] listening on http://127.0.0.1:${PORT}/poc/sync`);
    console.log(`[poc-sync] flow=${FLOW_PATH} startNode=${START_NODE}`);
});

process.on("uncaughtException", (err) => {
    console.error("[poc-sync] uncaughtException (should not happen - B6 guard failed):", err);
});
